 async function createLead(){const m=await membership();if(!m)return setNotice('No Clarifi workspace assigned.');const q=(s:string)=>(document.querySelector(s) as HTMLInputElement)?.value||'';const rel=clientType.toLowerCase().replaceAll(' ','_');const {data:client,error}=await supabase.from('clients').insert({organization_id:m.organization_id,name:q('#client-name'),email:q('#client-email')||null,phone:q('#client-phone')||null,address:q('#client-address')||null,relationship:rel}).select().single();if(error)return setNotice(error.message);const {error:je}=await supabase.from('jobs').insert({organization_id:m.organization_id,client_id:client.id,request:q('#client-request')||'General service request',details:q('#client-details')||null,status:'lead',service:q('#client-service')||null});if(je)return setNotice(je.message);setShowIntake(false);await loadData()}
