 const jobCards=(list:any[])=>list.length?<div className="job-list">{list.map(j=><article className="job-card" key={j.id}><div className="job-card-top"><span className="client-avatar">{(j.clients?.name||'C').slice(0,2).toUpperCase()}</span><div className="job-card-title"><h3>{j.clients?.name||'Client'}</h3><p>{j.request}</p></div><Badge status={j.status}/></div><div className="job-card-info"><span><Icon name="pin"/>{j.clients?.address||'Address needed'}</span><span><Icon name="clock"/>{j.scheduled_start?new Date(j.scheduled_start).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'Not scheduled'}</span></div><div className="job-card-footer"><span>{techs.find(t=>t.id===j.technician_id)?.name||'Unassigned'}</span><div className="button-wrap"><button className="secondary compact" onClick={()=>{selectJob(j.id);go('measurements')}}>Scope</button><button className="primary compact" onClick={()=>openQuote(j.id)}>Build quote</button>{j.status==='active'&&<AsyncButton className="secondary compact" onClick={()=>updateJob(j.id,{status:'completed'})}>Complete</AsyncButton>}</div></div></article>)}</div>:<Empty title={search||statusFilter!=='all'?'No matching jobs':'No jobs here yet'} detail={search||statusFilter!=='all'?'Try a different search or status filter.':'New requests and approved work will appear here.'} action={search||statusFilter!=='all'?<button className="secondary" onClick={()=>{setSearch('');setStatusFilter('all')}}>Clear filters</button>:newRequest}/>;

